# Own-wording items and gear of Grim Hollow Player's Guide (2024). Row shape as tvss_item.py.
# Weapons (baseitem) are built by the generator from the source stats. This file adds mastery texts and property notes (MASTERY, WDESC).
# AdvEq entries, ammunition and the Magazine are gear (GEAR rows: name, cost gp, weight lb, type, text). Hunter's Armor is the one magicvariant.
ITEMS = []; SP = {}; WPN = {}; GEAR = []
def add(name, typ, rar, att, text, **o):
    ITEMS.append((name, typ, rar, att, text, o))

# ---- the 9 new masteries (own wording)
MASTERY = {
 "Brutal": "Critical Hit range grows by 1 (a natural 19 or 20, or one point wider than any range you already have). On a Critical Hit with it, roll one extra damage die.",
 "Defending": "Reaction when a melee attack roll hits you: roll 1d4 and add it to your AC, including against that attack.",
 "Disarming": "If you hit with it during the Attack action, you can use a Bonus Action later that turn to try to disarm the target. Both of you make attack rolls with no Advantage or Disadvantage. If you win and the target can drop the weapon, it falls in the target's space. If you won with a Critical Hit, the weapon instead lands up to 15 ft away or in your free hand.",
 "Entangling": "If you hit with it during the Attack action, you can use a Bonus Action later that turn to entangle the target. It makes a Dexterity save (DC 10 plus your Proficiency Bonus) or is Grappled until it escapes or you let go of the weapon. Huge or larger targets pass automatically. It escapes with an action and a Strength (Athletics) or Dexterity (Acrobatics) check against the same DC. While it is Grappled, you cannot attack another creature with the weapon.",
 "Returning": "A ranged attack with it sends the weapon back to you right after the attack, hit or miss. You need a free hand to catch it.",
 "Scatter": "When you hit a creature with it during the Attack action, other creatures within the weapon's scatter range of the target (measured from any space the target occupies) take damage of the same type equal to 1 plus your Dexterity modifier, minimum 2.",
 "Set": "Reaction: when a creature enters your reach, make a melee attack against it with this weapon.",
 "Strong-Draw": "You have Disadvantage on attacks with it unless your Strength is 13 or higher. Add both your Strength and Dexterity modifiers to its damage.",
 "Swift": "After you miss with it, you have Advantage on your first attack with it against the same target before the end of your next turn. If that attack hits, it deals an extra 1d4 damage of the weapon's type.",
}
